'use server'

import { createClient } from '@/utils/supabase/server'
import { revalidatePath } from 'next/cache'

export type IncidentReport = {
  id: string
  created_at: string
  reporter_id: string
  subject_cadet_id: string
  description: string
  location: string
  incident_time: string
  action_taken: string | null
  status: 'pending' | 'handled' | 'converted'
  resolved_at: string | null
  resolved_by: string | null
  resolution_notes: string | null
  handled_by_id: string | null // NEW
  // Joins
  reporter: { first_name: string; last_name: string }
  subject: { first_name: string; last_name: string; company?: { company_name: string } }
  resolver?: { first_name: string; last_name: string }
  handler?: { first_name: string; last_name: string } // NEW join
}

// --- FETCHING ---

export async function getIncidents(filter: 'pending' | 'resolved' | 'all' = 'pending') {
  const supabase = createClient()
  const { data: { user } } = await supabase.auth.getUser()
  
  if (!user) return []

  let query = supabase
    .from('incident_reports')
    .select(`
      *,
      reporter:profiles!reporter_id(first_name, last_name),
      subject:profiles!subject_cadet_id(first_name, last_name, company:companies(company_name)),
      resolver:profiles!resolved_by(first_name, last_name),
      handler:profiles!handled_by_id(first_name, last_name)
    `)
    .order('created_at', { ascending: false })

  if (filter === 'pending') {
      query = query.eq('status', 'pending')
  } else if (filter === 'resolved') {
      query = query.in('status', ['handled', 'converted'])
  }

  const { data, error } = await query
  
  if (error) {
      // Log the full error to help debug if it persists
      console.error('Error fetching incidents:', JSON.stringify(error, null, 2))
      return []
  }

  return data as IncidentReport[]
}

// --- SUBMISSION (Teachers) ---

type IncidentPayload = {
    cadetIds: string[]
    description: string
    location: string
    incident_time: string 
    action_taken?: string
}

export async function submitIncident(payload: IncidentPayload) {
    const supabase = createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return { error: 'Unauthorized' }

    const rows = payload.cadetIds.map(cadetId => ({
        reporter_id: user.id,
        subject_cadet_id: cadetId,
        description: payload.description,
        location: payload.location,
        incident_time: payload.incident_time,
        action_taken: payload.action_taken || null,
        status: 'pending'
    }))

    const { error } = await supabase.from('incident_reports').insert(rows)
    if (error) return { error: error.message }
    
    revalidatePath('/incidents')
    return { success: true }
}

// --- RESOLUTION (TACs) ---

// Option A: Mark as "Handled" (No Demerits)
export async function resolveAsHandled(incidentId: string, notes: string, handledById: string) {
    const supabase = createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return { error: 'Unauthorized' }

    // 1. Update Incident
    const { data: incident, error: updateError } = await supabase
        .from('incident_reports')
        .update({
            status: 'handled',
            resolved_by: user.id,
            resolved_at: new Date().toISOString(),
            resolution_notes: notes,
            handled_by_id: handledById // Save who actually did the correction
        })
        .eq('id', incidentId)
        .select()
        .single()

    if (updateError) return { error: updateError.message }

    // 2. Log to Ledger (0 value history)
    const { error: ledgerError } = await supabase
        .from('tour_ledger')
        .insert({
            cadet_id: incident.subject_cadet_id,
            staff_id: handledById, // Attribute the action to the handler, not necessarily the TAC
            amount: 0,
            action: 'adjustment',
            comment: `Incident Handled: ${notes}`
        })

    if (ledgerError) console.error("Ledger logging failed:", ledgerError)

    revalidatePath('/incidents')
    return { success: true }
}

// Option B: Convert to Demerits
export async function convertToDemerit(incidentId: string, offenseTypeId: string, notes: string) {
    const supabase = createClient()
    const { data: { user } } = await supabase.auth.getUser()
    if (!user) return { error: 'Unauthorized' }

    const { data: incident } = await supabase.from('incident_reports').select('*').eq('id', incidentId).single()
    if (!incident) return { error: "Incident not found" }

    // *** FIX: Timezone / Future Date Constraint ***
    // We check if the incident time is > Now. If so, we clamp it to Now.
    // Ideally, we pass the incident time, but if the DB clock is behind the user clock, it fails.
    const incidentTime = new Date(incident.incident_time).getTime()
    const nowTime = new Date().getTime()
    const safeTimestamp = (incidentTime > nowTime) ? new Date().toISOString() : incident.incident_time;

    // 2. Call RPC (NO Auto-Append of old notes)
    const { error: rpcError } = await supabase.rpc('create_new_report', {
        p_subject_cadet_id: incident.subject_cadet_id,
        p_offense_type_id: offenseTypeId,
        p_notes: notes, // TAC writes fresh notes
        p_offense_timestamp: safeTimestamp // Clamped time
    })

    if (rpcError) return { error: "Failed to create report: " + rpcError.message }

    // 3. Link records
    const { data: newReport } = await supabase
        .from('demerit_reports')
        .select('id')
        .eq('submitted_by', user.id)
        .eq('subject_cadet_id', incident.subject_cadet_id)
        .order('created_at', { ascending: false })
        .limit(1)
        .single()

    if (newReport) {
        await supabase.from('demerit_reports').update({ linked_incident_id: incidentId }).eq('id', newReport.id)
    }

    // 4. Close Incident
    await supabase
        .from('incident_reports')
        .update({
            status: 'converted',
            resolved_by: user.id,
            resolved_at: new Date().toISOString(),
            resolution_notes: "Converted to Demerit Report"
        })
        .eq('id', incidentId)

    revalidatePath('/incidents')
    return { success: true }
}

// Helper: Get Faculty for Dropdown
export async function getFacultyList() {
    const supabase = createClient()
    const { data } = await supabase
        .from('profiles')
        .select('id, first_name, last_name, role:roles!inner(default_role_level)')
        .gte('role.default_role_level', 50)
        .order('last_name')
    
    return data?.map((p: any) => ({
        id: p.id,
        label: `${p.last_name}, ${p.first_name}`
    })) || []
}